// 勞基法 §53–55: an exit that owes no severance, by a worker with service on the Act who meets a retirement ground, is a retirement to settle.
if (ctx.entry.status !== 'SEALED') return false;
const to = ctx.entry.effective_range.to;
if (to == null) return false;
const extension = get(ctx.entry, 'employee_extension_data', {});
const facts = get(extension, 'facts', {});
if (ctx.lookup.severance_grounds.includes(get(extension, 'exit_facts.lsa_termination_ground', 'OTHER'))) return false;
const start = get(ctx.entry, 'service_started_on', ctx.entry.effective_range.from);
const professional = ctx.lookup.foreign_professional_covered === true && get(facts, 'foreign_professional', false) === true;
const spouse = get(facts, 'foreign_spouse_of_national', false) === true;
const foreign = get(ctx.entry, 'terms.residency_status', 'CITIZEN') === 'FOREIGNER' && !spouse && !professional;
const lsa = get(facts, 'statutory.LABOR_PENSION.elections.pension_system', 'NEW') === 'LSA';
const recorded = Number(get(extension, 'exit_facts.old_system_service_months', 0));
const on_the_act = lsa || foreign || recorded > 0 || start < ctx.lookup.old_system_cutoff;
if (!on_the_act) return false;
if (get(extension, 'exit_facts.retirement_disability', false) === true) return true;
const born = get(ctx.entry, 'payroll.date_of_birth', null);
if (born == null) return false;
const age = age_on(born, to);
const months = calendar_completed_months(start, add_days(to, 1));
return ctx.lookup.retirement_eligibility.some((band) => {
	if (!(months >= band.months)) return false;
	return band.age == null || age >= band.age;
});

